@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root {
--ink:#17231e;--muted:#758079;--paper:#f3f1e9;--line:#dfe2d8;--green:#204d3c;--lime:#d8f16a;--white:#fffefa;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
* {
box-sizing:border-box}
body {
margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);min-height:100vh}
.app {
max-width:1460px;margin:0 auto;padding:24px 36px 26px}
.topbar {
height:64px;display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
.brand {
display:flex;align-items:center;gap:12px}
.brand-mark {
width:42px;height:42px;border-radius:14px;background:var(--green);display:grid;place-items:center;color:var(--lime);font:700 22px var(--display);transform:rotate(-5deg)}
.brand-name {
font:700 18px var(--display);letter-spacing:-.6px}
.brand-sub {
font:500 10px var(--mono);letter-spacing:1.55px;color:var(--muted);margin-top:3px}
.top-meta {
display:flex;align-items:center;gap:12px}
.meet-tag,.live-tag {
display:flex;align-items:center;gap:8px;font:500 10px var(--mono);letter-spacing:.8px;color:#516058;background:#e8e9df;border:1px solid #dfe1d7;border-radius:100px;padding:10px 13px}
.live-dot {
height:7px;width:7px;border-radius:50%;background:#56a474;box-shadow:0 0 0 3px #d2e6d5}
.layout {
display:grid;grid-template-columns:minmax(0,1fr) 276px;gap:18px;align-items:stretch}
.main-column {
min-width:0}
.score-row {
display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-bottom:12px}
.score-card {
height:77px;background:var(--white);border:1px solid var(--line);border-radius:14px;padding:13px 17px;display:flex;align-items:center;justify-content:space-between}
.score-label {
font:500 10px var(--mono);letter-spacing:1px;text-transform:uppercase;color:var(--muted)}
.score-value {
font:700 23px var(--display);letter-spacing:-1px;margin-top:3px}
.score-value small {
font:500 12px var(--mono);color:var(--muted);letter-spacing:0}
.position-value {
display:flex;align-items:baseline;gap:5px}
.position-medal {
width:34px;height:34px;border-radius:11px;background:#eff4d8;color:#516329;display:grid;place-items:center;font-size:15px}
.progress-track {
height:5px;width:74px;border-radius:10px;background:#e6e8df;overflow:hidden;margin-top:8px}
.progress-track i {
display:block;width:0;height:100%;background:#cf754b;border-radius:10px;transition:width .2s}
.arena {
position:relative;height:min(63vh,660px);min-height:470px;border-radius:19px;overflow:hidden;background:#dfe8cc;border:1px solid #d2d9c8;box-shadow:0 13px 35px #28372b14}
.arena canvas {
position:absolute;inset:0;width:100%;height:100%;display:block}
.arena-topline {
position:absolute;top:17px;left:19px;right:19px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}
.track-chip {
background:#fffffff0;border:1px solid #ffffffb3;border-radius:10px;padding:9px 12px;font:500 10px var(--mono);letter-spacing:.8px;color:#34443a;box-shadow:0 3px 12px #25352412}
.track-chip strong {
font-weight:500;color:#a55332}
.lap-chip {
background:#183c30;color:#e8f4cf;border-radius:10px;padding:9px 12px;font:500 10px var(--mono);letter-spacing:.7px;box-shadow:0 3px 12px #25352418}
.arena-bottomline {
position:absolute;bottom:15px;left:17px;right:17px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}
.stamina-card {
width:245px;background:#fffffff2;border:1px solid #ffffffb8;border-radius:12px;padding:11px 13px;box-shadow:0 4px 15px #25352412}
.stamina-heading {
display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.stamina-heading span:first-child {
font:500 10px var(--mono);letter-spacing:.8px;color:#56645b}
.stamina-num {
font:500 11px var(--mono);color:#293a30}
.stamina-meter {
height:7px;background:#e6e9dd;border-radius:9px;overflow:hidden}
.stamina-fill {
height:100%;width:100%;background:#83a747;border-radius:9px;transition:width .15s,background .2s}
.pace-note {
font:500 10px var(--mono);color:#516058;margin-top:7px}
.lane-hint {
background:#fffffff0;border:1px solid #ffffffb8;border-radius:10px;padding:9px 11px;font:500 10px var(--mono);color:#59665d;box-shadow:0 4px 15px #25352412}
.sidebar {
display:flex;flex-direction:column;gap:12px}
.panel {
background:var(--white);border:1px solid var(--line);border-radius:15px;padding:17px}
.panel-heading {
display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.panel-title {
font:700 14px var(--display);letter-spacing:-.3px}
.eyebrow {
font:500 9px var(--mono);letter-spacing:1px;color:#858d84;text-transform:uppercase}
.distance-list {
display:flex;flex-direction:column;gap:7px}
.distance-option {
width:100%;text-align:left;background:#fffefa;border:1px solid #e3e5dc;border-radius:10px;padding:10px 11px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;color:var(--ink);font-family:var(--sans);transition:.15s}
.distance-option:hover {
border-color:#9aa68b;transform:translateY(-1px)}
.distance-option.selected {
background:#f0f4e3;border-color:#96a970;box-shadow:inset 0 0 0 1px #96a970}
.distance-name {
font-weight:700;font-size:12px}
.distance-detail {
font:10px var(--mono);color:#788278;margin-top:3px}
.distance-mark {
font:10px var(--mono);color:#8e978c}
.stats-panel {
flex:1}
.stats-intro {
font-size:11px;color:#788278;line-height:1.5;margin:-5px 0 13px}
.points-pill {
background:#edf1e3;border-radius:100px;padding:6px 9px;font:500 10px var(--mono);color:#4d6142}
.stat-row {
display:grid;grid-template-columns:1fr auto;align-items:center;padding:11px 0;border-top:1px solid #edf0e9}
.stat-copy strong {
font-size:12px;display:block}
.stat-copy span {
font:9px var(--mono);color:#838c82;display:block;margin-top:4px}
.stepper {
display:flex;align-items:center;gap:9px}
.stepper button {
width:25px;height:25px;border:1px solid #dce1d7;border-radius:8px;background:#fafbf6;color:#425249;font-size:16px;cursor:pointer;line-height:1}
.stepper button:hover:not(:disabled) {
background:#e8eddd}
.stepper button:disabled {
opacity:.35;cursor:not-allowed}
.stat-count {
font:500 12px var(--mono);min-width:12px;text-align:center}
.reset-stats {
border:0;background:none;color:#71816a;font:500 10px var(--mono);cursor:pointer;padding:7px 0 0}
.sidebar-bottom {
margin-top:auto}
.start-button {
display:flex;justify-content:center;align-items:center;gap:9px;width:100%;padding:14px;border:0;border-radius:11px;background:#204d3c;color:#f5f8e9;font:700 13px var(--display);cursor:pointer;box-shadow:0 4px 0 #15392b;transition:.15s}
.start-button:hover {
background:#286147;transform:translateY(-1px);box-shadow:0 5px 0 #15392b}
.start-button:active {
transform:translateY(2px);box-shadow:0 2px 0 #15392b}
.start-arrow {
font-size:17px;color:var(--lime)}
.small-note {
text-align:center;font:9px var(--mono);color:#828a80;margin:11px 0 1px}
.race-controls {
margin-top:12px;background:#fffefa;border:1px solid var(--line);border-radius:15px;padding:12px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px}
.control-info {
font:10px var(--mono);color:#7d877c;line-height:1.6}
.control-info strong {
color:#48574c;font-weight:500}
.steer-controls {
display:flex;gap:7px}
.control-btn {
height:43px;min-width:51px;border:1px solid #dfe3d9;border-radius:11px;background:#f8f9f3;color:#314438;cursor:pointer;user-select:none;touch-action:none;font:700 18px var(--display);box-shadow:0 2px 0 #e1e4dc}
.control-btn:hover {
background:#eef1e6}
.control-btn:active,.control-btn.pressed {
background:#dce7cd;transform:translateY(1px);box-shadow:none}
.boost-btn {
height:44px;padding:0 17px;min-width:154px;border:0;border-radius:11px;background:#d8f16a;color:#26341e;cursor:pointer;user-select:none;touch-action:none;font:700 11px var(--mono);letter-spacing:.5px;box-shadow:0 3px 0 #abc64e}
.boost-btn:hover {
background:#e1f68d}
.boost-btn:active,.boost-btn.pressed {
transform:translateY(2px);box-shadow:0 1px 0 #abc64e}
.boost-btn span {
font-size:15px;margin-right:6px;vertical-align:-1px}
.keyboard-hint {
text-align:right;font:10px var(--mono);line-height:1.7;color:#788278}
.keyboard-hint kbd {
font:10px var(--mono);padding:2px 4px;border:1px solid #dfe2da;border-radius:4px;background:#f9faf5;color:#465449}
.overlay {
position:absolute;inset:0;z-index:3;display:grid;place-items:center;padding:22px;background:#13261b66;backdrop-filter:blur(4px)}
.dialog {
width:min(440px,100%);background:#fffefa;border:1px solid #ffffffb3;border-radius:18px;padding:25px 27px;box-shadow:0 22px 60px #10201542;text-align:center}
.dialog-kicker {
font:500 10px var(--mono);letter-spacing:1.7px;color:#829177;text-transform:uppercase}
.dialog h1 {
font:700 30px var(--display);letter-spacing:-1.3px;margin:10px 0 8px}
.dialog p {
font-size:12px;line-height:1.65;color:#6f7a70;margin:0 auto 18px;max-width:345px}
.dialog-flag {
font-size:29px;margin-bottom:8px}
.dialog .start-button {
max-width:260px;margin:0 auto}
.results-grid {
display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:17px 0}
.result-cell {
background:#f1f3eb;border-radius:10px;padding:10px}
.result-cell span {
display:block;font:9px var(--mono);color:#808b80;text-transform:uppercase;letter-spacing:.7px}
.result-cell strong {
display:block;font:700 18px var(--display);margin-top:5px}
.hidden {
display:none!important}

@media(max-width:1000px) {
.app {
padding:18px 22px}
.layout {
grid-template-columns:minmax(0,1fr) 255px;gap:12px}
.arena {
height:59vh;min-height:430px}
.score-card {
padding:11px 13px}
.sidebar .panel {
padding:14px}
}

@media(max-width:760px) {
.app {
