.topbar {
height:48px;margin-bottom:12px}
.brand-mark {
width:36px;height:36px;border-radius:12px}
.brand-name {
font-size:16px}
.brand-sub {
font-size:8px}
.meet-tag {
display:none}
.live-tag {
font-size:9px;padding:8px 10px}
.layout {
display:flex;flex-direction:column}
.score-row {
gap:7px;margin-bottom:8px}
.score-card {
height:65px;padding:9px 10px;border-radius:11px}
.score-label {
font-size:8px;letter-spacing:.6px}
.score-value {
font-size:19px}
.position-medal {
height:28px;width:28px}
.progress-track {
width:48px;height:4px;margin-top:6px}
.arena {
height:55vh;min-height:380px;max-height:560px;border-radius:15px}
.arena-topline {
top:11px;left:11px;right:11px}
.track-chip,.lap-chip {
font-size:9px;padding:8px 9px}
.arena-bottomline {
left:10px;right:10px;bottom:10px}
.stamina-card {
width:190px;padding:9px 10px}
.lane-hint {
font-size:9px;padding:8px}
.race-controls {
margin-top:8px;padding:9px;grid-template-columns:1fr auto 1fr;gap:5px}
.control-info {
font-size:8px}
.control-btn {
height:40px;min-width:43px}
.boost-btn {
height:41px;min-width:118px;padding:0 9px;font-size:9px}
.boost-btn span {
font-size:13px}
.keyboard-hint {
font-size:8px}
.keyboard-hint kbd {
font-size:8px}
.sidebar {
display:grid;grid-template-columns:1fr 1fr;gap:8px}
.sidebar .panel {
padding:12px}
.panel-title {
font-size:13px}
.distance-option {
padding:8px}
.distance-name {
font-size:11px}
.distance-detail {
font-size:8px}
.stats-intro {
font-size:10px}
.stat-row {
padding:8px 0}
.stat-copy strong {
font-size:11px}
.stat-copy span {
font-size:8px}
.stepper {
gap:6px}
.stepper button {
width:22px;height:22px}
.sidebar-bottom {
display:flex;flex-direction:column;justify-content:center}
.small-note {
font-size:8px}
.dialog {
padding:21px 19px}
.dialog h1 {
font-size:26px}
}

@media(max-width:430px) {
.arena {
min-height:355px;height:50vh}
.lane-hint {
display:none}
.score-card {
height:59px;padding:8px}
.score-label {
font-size:7px}
.score-value {
font-size:17px}
.stamina-card {
width:175px}
.race-controls {
grid-template-columns:auto 1fr auto}
.control-info {
display:none}
.keyboard-hint {
text-align:right}
.boost-btn {
min-width:105px}
.sidebar {
grid-template-columns:1fr}
.sidebar-bottom {
padding:3px 0}
.layout {
gap:10px}
}

